def _score_each_word_on_new_line(text: str) -> float:
    value = text.translate(str.maketrans('', '', string.punctuation))
    lines = [ln.strip() for ln in value.strip().split('\n') if ln.strip()]
    words = value.strip().split()
    if not words:
        return 0.0
    if any(len(w) > 50 for w in words):
        return 0.0
    # Guard against short concatenated single-line responses
    if len(lines) == 1 and len(words) <= 3 and any(len(w) >= 20 for w in words):
        return 0.0
    single_word_lines = sum(1 for ln in lines if len(ln.split()) == 1)
    return min(single_word_lines / len(words), 1.0)
